        let memory = props
            .and_then(|p| p.get("memory"))
            .and_then(|v| v.as_u64())
            .unwrap_or(512) as u32;

        let swap = props
            .and_then(|p| p.get("swap"))
            .and_then(|v| v.as_u64())
            .unwrap_or(512) as u32;

        let storage = props
            .and_then(|p| p.get("storage"))
            .and_then(|v| v.as_str())
            .unwrap_or("local-btrfs");

        let rootfs_size = props
            .and_then(|p| p.get("rootfs_size"))
            .and_then(|v| v.as_u64())
