   489	        if let Some(ref ipv4) = config.tunable.ipv4 {
   490	            if ipv4.enabled {
   491	                if let Some(ref addresses) = ipv4.address {
   492	                    for addr in addresses {
   493	                        match op_network::rtnetlink::add_ipv4_address(
   494	                            &config.name,
   495	                            &addr.ip,
   496	                            addr.prefix,
   497	                        )
   498	                        .await
   499	                        {
   500	                            Ok(_) => {
   501	                                log::info!(
   502	                                    "Added IP {}/{} to {} via rtnetlink",
   503	                                    addr.ip,
   504	                                    addr.prefix,
   505	                                    config.name
   506	                                );
   507	                            }
   508	                            Err(e) => {
   509	                                log::warn!(
   510	                                    "Failed to add IP {} (may already exist): {}",
   511	                                    addr.ip,
   512	                                    e
   513	                                );
   514	                            }
   515	                        }
   516	                    }
   517	                }
   518	
   519	                // Configure gateway if specified via rtnetlink (native netlink)
   520	                if let Some(ref gateway) = ipv4.gateway {
   521	                    // Delete existing default route (ignore errors)
   522	                    let _ = op_network::rtnetlink::del_default_route().await;
   523	
   524	                    // Add new default route
   525	                    match op_network::rtnetlink::add_default_route(&config.name, gateway).await {
   526	                        Ok(_) => {
   527	                            log::info!(
   528	                                "Added default route via {} on {} via rtnetlink",
   529	                                gateway,
   530	                                config.name
   531	                            );
   532	                        }
   533	                        Err(e) => {
   534	                            log::warn!("Failed to add default route: {}", e);
   535	                        }
   536	                    }
   537	                }
   538	            }
   539	        }
   540	
   541	        log::info!("Finished apply_ovs_config for {}", config.name);
   542	        Ok(())
   543	    }
