   545	    /// Apply OVS internal port configuration
   546	    pub async fn apply_ovs_port_config(&self, config: &InterfaceConfig) -> Result<()> {
   547	        log::info!("Starting apply_ovs_port_config for {}", config.name);
   548	
   549	        // Internal ports are created as part of their parent bridge
   550	        // This function handles IP configuration only
   551	
   552	        // Determine L3 driver (default to rtnetlink)
   553	        let l3_driver = config.tunable.l3_driver.as_deref().unwrap_or("rtnetlink");
   554	
   555	        if l3_driver == "rtnetlink" {
   556	            // Bring interface up via native rtnetlink
   557	            if let Err(e) = op_network::rtnetlink::link_up(&config.name).await {
   558	                log::warn!("Failed to bring port up: {}", e);
   559	            }
   560	
   561	            // Configure IPv4 if specified via rtnetlink
   562	            if let Some(ref ipv4) = config.tunable.ipv4 {
   563	                if ipv4.enabled {
   564	                    if let Some(ref addresses) = ipv4.address {
   565	                        for addr in addresses {
   566	                            match op_network::rtnetlink::add_ipv4_address(
   567	                                &config.name,
   568	                                &addr.ip,
   569	                                addr.prefix,
   570	                            )
   571	                            .await
   572	                            {
   573	                                Ok(_) => {
   574	                                    log::info!(
   575	                                        "Added IP {}/{} to {} via rtnetlink",
   576	                                        addr.ip,
   577	                                        addr.prefix,
   578	                                        config.name
   579	                                    );
   580	                                }
   581	                                Err(e) => {
   582	                                    log::warn!(
   583	                                        "Failed to add IP {} (may already exist): {}",
   584	                                        addr.ip,
   585	                                        e
   586	                                    );
   587	                                }
   588	                            }
   589	                        }
   590	                    }
   591	
   592	                    // Configure gateway if specified
   593	                    if let Some(ref gateway) = ipv4.gateway {
   594	                        let _ = op_network::rtnetlink::del_default_route().await;
   595	                        match op_network::rtnetlink::add_default_route(&config.name, gateway).await
   596	                        {
   597	                            Ok(_) => {
   598	                                log::info!("Added default route via {} via rtnetlink", gateway);
   599	                            }
   600	                            Err(e) => {
   601	                                log::warn!("Failed to add default route: {}", e);
   602	                            }
   603	                        }
   604	                    }
   605	                }
   606	            }
   607	
   608	            // Update /etc/network/interfaces for persistence
   609	            self.update_interfaces_file(&config.name, None, &config.tunable.ipv4)
   610	                .await?;
   611	        } else {
   612	            log::warn!("Unsupported L3 driver '{}' for {}", l3_driver, config.name);
   613	        }
   614	
   615	        log::info!("Finished apply_ovs_port_config for {}", config.name);
   616	        Ok(())
   617	    }
